SELECT regiao, SUM(receita) AS receita_total
FROM vendas GROUP BY regiao
HAVING SUM(receita) > 50000;

WITH clientes AS (
  SELECT cliente_id, COUNT(*) AS pedidos FROM vendas GROUP BY cliente_id
)
SELECT v.pedido_id, v.cliente_id, v.canal, c.pedidos
FROM vendas AS v INNER JOIN clientes AS c ON v.cliente_id = c.cliente_id;

WITH meses AS (
 SELECT YEAR(data) AS ano, MONTH(data) AS mes, receita FROM vendas
)
SELECT ano, mes, SUM(receita) AS total
FROM meses GROUP BY ano, mes ORDER BY ano, mes;

SELECT pedido_id, regiao, receita,
 DENSE_RANK() OVER (PARTITION BY regiao ORDER BY receita DESC) AS ranking
FROM vendas;

WITH diario AS (
 SELECT data, SUM(receita) AS receita FROM vendas GROUP BY data
)
SELECT data, receita, SUM(receita) OVER (
 ORDER BY data ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
) AS acumulado FROM diario ORDER BY data;

SELECT ticket_id, LTRIM(RTRIM(canal)) AS canal,
 COALESCE(CAST(satisfacao AS varchar(10)), 'Sem avaliação') AS avaliacao
FROM atendimento;
